-- Jeremy Tech: datos iniciales para MariaDB 10.2+
-- Requiere database/jeremy_tech_estructura.sql.
-- Uso: mariadb -h 127.0.0.1 -u root -p < database/jeremy_tech_datos.sql
-- Solo datos de catalogo, cuentas y configuracion. Sin pedidos, carritos,
-- pagos, auditoria, analitica ni tokens.

SET NAMES utf8mb4;
SET TIME_ZONE='+00:00';
SET FOREIGN_KEY_CHECKS=0;
USE `jeremy_tech`;

START TRANSACTION;


COMMIT;

SET FOREIGN_KEY_CHECKS=1;
