INSERT INTO `chatbot_faq` (`id`, `pregunta`, `palabras_clave`, `respuesta`, `activo`, `orden`, `creado_en`, `actualizado_en`) VALUES (1,'¿Cómo busco un producto?','buscar, buscador, encontrar, sugerencias, catalogo','Usa el buscador superior: acepta nombre, modelo, SKU o categoría. Mientras escribes verás sugerencias con imagen y precio; también puedes navegar por las categorías del menú.',1,10,'2026-10-28 01:03:00','2026-10-28 01:10:43');
INSERT INTO `chatbot_faq` (`id`, `pregunta`, `palabras_clave`, `respuesta`, `activo`, `orden`, `creado_en`, `actualizado_en`) VALUES (2,'¿Cómo cambio la moneda?','moneda, dolar, dolares, soles, pen, usd, eur','Abre el selector de moneda en la barra superior y elige PEN, USD, EUR, GBP, BRL, ARS, CLP o COP. La conversión es referencial y el pedido se registra en soles (PEN).',1,20,'2026-10-28 01:03:00','2026-10-28 01:03:00');
INSERT INTO `chatbot_faq` (`id`, `pregunta`, `palabras_clave`, `respuesta`, `activo`, `orden`, `creado_en`, `actualizado_en`) VALUES (3,'¿Cómo sigo mi pedido?','pedido, seguimiento, rastrear, historial, estado','Inicia sesión y abre Mis Pedidos. Ahí verás el estado, el pago y la línea de tiempo de tu compra. Si no tienes cuenta, puedes crear una desde registro.',1,30,'2026-10-28 01:03:00','2026-10-28 01:03:00');
INSERT INTO `chatbot_faq` (`id`, `pregunta`, `palabras_clave`, `respuesta`, `activo`, `orden`, `creado_en`, `actualizado_en`) VALUES (4,'¿Qué métodos de pago aceptan?','pago, pagar, tarjeta, yape, plin, transferencia, contraentrega','Aceptamos tarjeta de crédito o débito, Yape/Plin, transferencia bancaria y pago contraentrega. En esta demostración los pagos son simulados y no se realiza ningún cobro real.',1,40,'2026-10-28 01:03:00','2026-10-28 01:03:00');
INSERT INTO `chatbot_faq` (`id`, `pregunta`, `palabras_clave`, `respuesta`, `activo`, `orden`, `creado_en`, `actualizado_en`) VALUES (5,'¿Cuánto cuesta el envío?','envio, envios, tarifa, delivery, zona','Depende de la zona de entrega. Revisa la tabla completa en Envíos y devoluciones. El recojo en tienda es gratuito.',1,50,'2026-10-28 01:03:00','2026-10-28 01:03:00');
INSERT INTO `chatbot_faq` (`id`, `pregunta`, `palabras_clave`, `respuesta`, `activo`, `orden`, `creado_en`, `actualizado_en`) VALUES (6,'¿Puedo recoger mi pedido en tienda?','recojo, recoger, sede, sucursal','Sí. Elige la modalidad de recojo al finalizar la compra. Nuestra dirección es La Paz Soldán, frente a Los Portales, La Joya – Arequipa.',1,60,'2026-10-28 01:03:00','2026-10-28 01:03:00');
INSERT INTO `chatbot_faq` (`id`, `pregunta`, `palabras_clave`, `respuesta`, `activo`, `orden`, `creado_en`, `actualizado_en`) VALUES (7,'¿Cómo devuelvo un producto?','devolver, devolucion, devoluciones, reembolso','Escríbenos dentro de los 30 días posteriores a la recepción, con el producto sin uso y en su empaque original. Te indicaremos los pasos para la devolución o garantía.',1,70,'2026-10-28 01:03:00','2026-10-28 05:36:37');
INSERT INTO `chatbot_faq` (`id`, `pregunta`, `palabras_clave`, `respuesta`, `activo`, `orden`, `creado_en`, `actualizado_en`) VALUES (8,'¿Los productos tienen garantía?','garantia, garantias, original, fabricante','Sí. Todos los productos son originales y la garantía depende del fabricante y del modelo; la ficha del producto muestra la cobertura aplicable.',1,80,'2026-10-28 01:03:00','2026-10-28 01:03:00');
INSERT INTO `chatbot_faq` (`id`, `pregunta`, `palabras_clave`, `respuesta`, `activo`, `orden`, `creado_en`, `actualizado_en`) VALUES (9,'¿Mis datos y pagos están seguros?','seguridad, seguro, datos, privacidad, contrasena','Las contraseñas se almacenan con hash, los formularios usan tokens CSRF y las consultas son preparadas. No almacenamos datos de tarjeta. En esta demo los pagos no son reales.',1,90,'2026-10-28 01:03:00','2026-10-28 01:03:00');
INSERT INTO `chatbot_faq` (`id`, `pregunta`, `palabras_clave`, `respuesta`, `activo`, `orden`, `creado_en`, `actualizado_en`) VALUES (10,'¿Cómo contacto a una persona?','contacto, whatsapp, correo, telefono, asesor','Puedes escribirnos por WhatsApp al +51 999 000 000, al correo soporte@example.com o usar el chatbot de la tienda.',1,100,'2026-10-28 01:03:00','2026-10-29 04:52:49');
